<script setup lang="ts">
import type{components}from'~/api/schema';import{unwrap}from'~/api/client';import{displayError}from'~/utils/errors';import{formatDate,formatRupiah,statusLabel}from'~/utils/format';type Journal=components['schemas']['Journal'];type Audit=components['schemas']['AuditLog'];definePageMeta({middleware:['auth','admin']});const api=useMarketplaceApi();const journals=ref<Journal[]>([]);const audits=ref<Audit[]>([]);const selected=ref<Audit>();const pending=ref(true);const message=ref('');async function load(){pending.value=true;const r=await Promise.allSettled([api.GET('/admin/journals',{params:{query:{limit:100}},cache:'no-store'}).then(unwrap),api.GET('/admin/audit-logs',{params:{query:{limit:100}},cache:'no-store'}).then(unwrap)]);if(r[0].status==='fulfilled')journals.value=r[0].value.items;if(r[1].status==='fulfilled')audits.value=r[1].value.items;if(r.every(x=>x.status==='rejected'))message.value=displayError((r[0]as PromiseRejectedResult).reason).message;pending.value=false}onMounted(()=>{void load()});useSeoMeta({title:'Jurnal dan audit — Niaga'})
</script>
<template><main id="main-content" class="page-shell"><PortalNav area="admin"/><div class="section-heading"><div><p class="eyebrow">Read only</p><h1>Jurnal dan audit</h1></div></div><p v-if="message" class="surface" role="status">{{message}}</p><ApiState :pending="pending"><section><h2>Jurnal akuntansi</h2><div class="table-wrap surface"><table><thead><tr><th>Waktu</th><th>Event key</th><th>Status</th><th>Debit</th><th>Kredit</th></tr></thead><tbody><tr v-for="item in journals" :key="item.id"><td>{{formatDate(item.created_at)}}</td><td><code>{{item.event_key}}</code></td><td><span class="badge">{{statusLabel(item.status)}}</span></td><td>{{formatRupiah(item.lines.reduce((s,x)=>s+x.debit,0))}}</td><td>{{formatRupiah(item.lines.reduce((s,x)=>s+x.credit,0))}}</td></tr><tr v-if="!journals.length"><td colspan="5">Belum ada jurnal.</td></tr></tbody></table></div></section><section class="section"><h2>Audit log tersamarkan</h2><div class="admin-split"><div class="table-wrap surface"><table><thead><tr><th>Waktu</th><th>Entitas</th><th>Aksi</th></tr></thead><tbody><tr v-for="item in audits" :key="item.id" tabindex="0" @click="selected=item" @keydown.enter="selected=item"><td>{{formatDate(item.created_at)}}</td><td>{{item.entity_type}}<small>{{item.entity_id.slice(0,8)}}</small></td><td>{{item.action}}</td></tr></tbody></table></div><aside class="surface audit-viewer"><h2>Perubahan</h2><template v-if="selected"><p><strong>{{selected.action}}</strong></p><p>Actor: {{selected.actor_id||'system'}}</p><p>Entity: {{selected.entity_type}} / {{selected.entity_id}}</p><pre>{{JSON.stringify(selected.changes_redacted,null,2)}}</pre></template><p v-else class="muted">Pilih audit log untuk melihat before/after yang sudah disensor backend.</p></aside></div></section></ApiState></main></template>
